for i,(prompt,opts,ans,ex,strategy) in enumerate(DATA,1):
 p=D/f'question-science-content-na-iv-7-{i}.json'; old=json.loads(p.read_text()); text=opts[ord(ans)-65]
 old.update({'prompt':prompt,'options':[{'id':chr(65+j),'text':x} for j,x in enumerate(opts)],'answer':{'value':ans,'explanation':ex+f' 正確答案為選項 {ans}：「{text}」。'},'solutionStrategy':strategy,'solutionSteps':['定位概念：圈出 Na-Ⅳ-7 的減量、回收、再利用、綠能或永續指標。','整理證據：分開服務量、能源與物質流、生命週期、成本與公平性。',f'套用原理：{ex}',f'排除干擾：檢查是否只看單一階段或單一指標，正確選項是「{text}」。',f'最後回查：答案「{text}」符合題幹，沒有把局部改善誇大成整體永續。'],'reviewStatus':'draft','updatedAt':'2026-09-08'})
